head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > resize]<br/>마우스 Drag 에 의한 Column 의 너비(Width) 변경을 허용할지 설정합니다.",
    "validation" : [
        "true(기본값) 설정 시, Header Column 의 오른쪽 경계를 마우스로 Drag 하여 Column 의 너비를 변경할 수 있습니다.",
        "미설정 시, Header Column 의 오른쪽 경계를 마우스로 Drag 하여 Column 의 너비를 변경할 수 있습니다.",
        "true 설정 시, Header Column 의 오른쪽 경계를 더블클릭하면 데이터의 최대 길이에 맞게 너비가 자동 조정됩니다.",
        "false 설정 시, 마우스 Drag 로 Column 의 너비를 변경할 수 없습니다.",
        "resize=true 일때 Header Column 오른쪽 경계 마우스 오버 시 포인터가 'col-resize' 로 변경됩니다.",
        "setColumnWidth(), setRowNumColumnWidth(), setRowStatusColumnWidth() 등 메소드에 의한 너비 변경은 resize 속성값과 관계없이 동작합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - con_resize(gdl_boolean) : 미설정('') / true / false. resize 는 @dynamic N 이라 con 변경은 Target 재생성으로 반영.
//    · 미설정('') : resize 속성 자체 미설정 = 엔진 기본값(true) → Drag 로 너비 변경 가능
//    · true       : resize="true" → Drag/더블클릭 autofit 가능
//    · false      : resize="false" → Drag/더블클릭으로 너비 변경 불가
//  - RowNum/RowStatus 표시 : setRowNumColumnWidth/setRowStatusColumnWidth 검증 대상 확보(메소드 무관 동작)
//  - col1 은 긴 데이터 + 좁은 초기 너비 → 경계 더블클릭 autofit 관찰용
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // resize 옵션 (gdl_boolean → getText 로 '' / true / false 라벨 사용)
    let resize = con_resize.getText();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] resize=(현재 [' + (resize === '' ? '미설정' : resize) + ']). RowNum/RowStatus 표시. col1 은 긴 데이터(좁은 초기 너비)로 더블클릭 autofit 관찰용. con 변경은 Target 재생성 버튼으로 반영.\n[절차] Header Column 오른쪽 경계를 좌우로 Drag → 너비 변경. 경계 더블클릭 → 데이터 최대 길이 autofit. 경계 마우스 오버 → 포인터 col-resize.\n[확인] [컬럼 너비 확인] 버튼으로 너비 변화를 관찰. resize=false 면 Drag/더블클릭으로 너비 불변. [메소드 너비 변경] 버튼은 resize 값과 무관하게 동작."', '', 'label1');

    // GridView 와 바인딩할 DataList (4 Column, 4 Row). col1 은 긴 데이터
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "col1": "가나다라마바사아자차카타파하", "col2": "B1", "col3": "C1", "col4": "D1" },
        { "col1": "가나다라마바사아자차카타파하", "col2": "B2", "col3": "C2", "col4": "D2" },
        { "col1": "가나다라마바사아자차카타파하", "col2": "B3", "col3": "C3", "col4": "D3" },
        { "col1": "가나다라마바사아자차카타파하", "col2": "B4", "col3": "C4", "col4": "D4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // con 값이 있으면 resize 속성 부여, 미설정이면 속성 자체 미부여(엔진 기본값 true)
    let strAttr = '';
    if (resize !== '') {
        strAttr += ' resize="' + resize + '"';
    }

    // target 그리드 직접 구성 (RowNum/RowStatus 표시, col1 좁은 초기 너비)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + strAttr + ' dataList="data:dlt_bind" rowNumVisible="true" rowNumHeaderValue="No." rowStatusVisible="true" rowStatusHeaderValue="St." id="" style="width:600px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="resize 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hcol1" value="col1(H)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2(H)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3(H)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol4" value="col4(H)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
};



// [컬럼 너비 확인] : 현재 각 Column 의 너비 출력
//  - Drag/더블클릭(autofit) 전후로 클릭하여 너비 변화를 관찰(@propval true / false 검증)
//  - 인덱스 : 0=RowNum, 1=RowStatus, 2=col1, 3=col2, 4=col3, 5=col4 (RowNum/RowStatus 포함)
scwin.btn_checkWidth_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====현재 컬럼 너비=====");
    bottom.setReturnValue("RowNum(0) : " + target1.getColumnWidth(0));
    bottom.setReturnValue("RowStatus(1) : " + target1.getColumnWidth(1));
    bottom.setReturnValue("col1(2) : " + target1.getColumnWidth(2));
    bottom.setReturnValue("col2(3) : " + target1.getColumnWidth(3));
    bottom.setReturnValue("col3(4) : " + target1.getColumnWidth(4));
    bottom.setReturnValue("col4(5) : " + target1.getColumnWidth(5));
};



// [메소드 너비 변경] : setColumnWidth / setRowNumColumnWidth / setRowStatusColumnWidth 로 너비 변경
//  - resize=false 여도 메소드는 항상 동작(@spec) → 실행 후 너비가 지정값으로 변경됨을 확인
//  - setColumnWidth 는 Body Column 정보(ID) 로 대상 지정. getColumnWidth 는 RowNum/RowStatus 포함 전체 인덱스(col1=2)
scwin.btn_methodResize_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====메소드 너비 변경 (현재 resize=[" + (con_resize.getText() === '' ? '미설정' : con_resize.getText()) + "])=====");

    // col1 Body Column = 200px, RowNum = 60px, RowStatus = 70px
    target1.setColumnWidth("col1", 200);
    target1.setRowNumColumnWidth(60);
    target1.setRowStatusColumnWidth(70);

    bottom.setReturnValue("setColumnWidth('col1', 200) -> col1 width : " + target1.getColumnWidth(2));
    bottom.setReturnValue("setRowNumColumnWidth(60) -> RowNum width : " + target1.getColumnWidth(0));
    bottom.setReturnValue("setRowStatusColumnWidth(70) -> RowStatus width : " + target1.getColumnWidth(1));
};
